'use strict';
(()=>{
 const button=document.getElementById('install-app'),help=document.getElementById('install-help'),status=document.getElementById('install-status'),offline=document.getElementById('offline-status'),clear=document.getElementById('clear-offline'),update=document.getElementById('update-app');
 let promptEvent=null,registration=null,removed=false;
 function installed(){return window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;}
 function installState(){if(installed()){button.hidden=true;status.textContent='Running as an installed app.';}else{button.textContent=promptEvent?'Install Baseera':'Installation help';}}
 window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();promptEvent=event;installState();});
 window.addEventListener('appinstalled',()=>{promptEvent=null;status.textContent='Baseera installed. Open it from your apps.';button.hidden=true;});
 button.addEventListener('click',async()=>{if(!promptEvent){help.open=true;help.scrollIntoView({block:'nearest',behavior:'smooth'});return;}const event=promptEvent;promptEvent=null;try{await event.prompt();const choice=await event.userChoice;status.textContent=choice.outcome==='accepted'?'Installation requested. Follow your browser’s confirmation.':'Installation cancelled. You can keep using the website.';}catch{help.open=true;status.textContent='Use your browser menu to install.';}installState();});
 installState();
 function watchUpdate(reg){if(reg.waiting){update.hidden=false;update.onclick=()=>{const confirmed=window.confirm('Load the new app version? Your current practice answers will be cleared.');if(!confirmed)return;let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloading){reloading=true;location.reload();}},{once:true});reg.waiting?.postMessage({type:'ACTIVATE_UPDATE'});};}reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)watchUpdate(reg);});});}
 async function checkOffline(){if(removed||!registration?.active)return;const channel=new MessageChannel();const timer=setTimeout(()=>{offline.textContent='Offline readiness could not be confirmed. Keep this page open while connected.';channel.port1.close();},8000);channel.port1.onmessage=event=>{clearTimeout(timer);channel.port1.close();if(removed)return;const ready=event.data?.ready;offline.textContent=ready?(navigator.onLine?'Offline lessons ready on this device.':'Offline mode · lessons and practice are available.'):'Offline download is incomplete. Reopen while connected to try again.';clear.hidden=!ready;};registration.active.postMessage({type:'OFFLINE_STATUS'},[channel.port2]);}
 clear.addEventListener('click',async()=>{removed=true;clear.disabled=true;try{const regs=await navigator.serviceWorker.getRegistrations();for(const reg of regs){const script=reg.active?.scriptURL||reg.waiting?.scriptURL||reg.installing?.scriptURL;if(script&&new URL(script).pathname==='/sw.js')await reg.unregister();}for(const name of await caches.keys())if(name.startsWith('baseera-offline-'))await caches.delete(name);offline.textContent='Offline lessons removed. Reopening this app online will download them again.';clear.hidden=true;update.hidden=true;}catch{removed=false;clear.disabled=false;offline.textContent='Could not remove offline files. Use your browser’s site-data settings.';}});
 if(!('serviceWorker' in navigator)||!window.isSecureContext){offline.textContent='Offline mode is unavailable in this browser. Use the online version.';return;}
 offline.textContent='Downloading lessons and illustrations for offline use…';
 navigator.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'}).then(reg=>{registration=reg;watchUpdate(reg);if(reg.active)checkOffline();else{const worker=reg.installing||reg.waiting;worker?.addEventListener('statechange',()=>{if(worker.state==='activated')checkOffline();if(worker.state==='redundant')offline.textContent='Offline setup did not finish. Reopen while connected and signed in.';});}navigator.serviceWorker.ready.then(()=>checkOffline());}).catch(()=>{offline.textContent='Offline setup is unavailable here. You can still use Baseera online.';});
 navigator.serviceWorker.addEventListener('controllerchange',()=>checkOffline());window.addEventListener('online',checkOffline);window.addEventListener('offline',checkOffline);
})();
